class Solution {
public:
    vector<vector<int>> highFive(vector<vector<int>>& items) {
        map<int, vector<int>> scores;
        for (const auto& item : items) {
            scores[item[0]].push_back(item[1]);
        }

        vector<vector<int>> res;
        for (auto& [sid, list] : scores) {
            sort(list.rbegin(), list.rend());
            int sum = 0;
            for (int i = 0; i < 5; ++i) sum += list[i];
            res.push_back({sid, sum / 5});
        }
        return res;
    }
};

class Solution {
    public int[][] highFive(int[][] items) {
        Map<Integer, List<Integer>> scores = new TreeMap<>();
        for (int[] item : items) {
            scores.computeIfAbsent(item[0], k -> new ArrayList<>()).add(item[1]);
        }

        int[][] res = new int[scores.size()][2];
        int idx = 0;
        for (Map.Entry<Integer, List<Integer>> entry : scores.entrySet()) {
            List<Integer> list = entry.getValue();
            Collections.sort(list, Collections.reverseOrder());
            int sum = 0;
            for (int i = 0; i < 5; ++i) sum += list.get(i);
            res[idx][0] = entry.getKey();
            res[idx][1] = sum / 5;
            idx++;
        }
        return res;
    }
}

var highFive = function(items) {
    const scores = new Map();
    for (const [sid, sc] of items) {
        if (!scores.has(sid)) scores.set(sid, []);
        scores.get(sid).push(sc);
    }

    const sids = [...scores.keys()].sort((a, b) => a - b);
    const res = [];
    for (const sid of sids) {
        const top5 = scores.get(sid).sort((a, b) => b - a).slice(0, 5);
        const avg = Math.floor(top5.reduce((a, b) => a + b, 0) / 5);
        res.push([sid, avg]);
    }
    return res;
};
